use std::{collections::BTreeSet, fs, io::{Read,Write}, path::Path, time::Instant};
use vlajmaji::{lexicon::*, search::*, store::*};
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
const ROOT:&str="/tmp/vlajmaji-p01-a03-arc-review";
fn sha(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn file_sha(p:&Path)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;1048576];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn stage(name:&str)->Instant{println!("{}",json!({"stage_start":name}));std::io::stdout().flush().unwrap();Instant::now()}
fn done(name:&str,t:Instant){println!("{}",json!({"stage_done":name,"elapsed_s":t.elapsed().as_secs_f64()}));std::io::stdout().flush().unwrap();}
fn tuple(o:&OccurrenceRef)->String{let mut b=Vec::new();for x in [&o.capture.namespace,&o.capture.sha256,&o.locator]{b.extend((x.len() as u64).to_be_bytes());b.extend(x.as_bytes());}b.iter().map(|x|format!("{x:02x}")).collect()}
fn save(name:&str,v:&Value){let mut b=serde_json::to_vec(v).unwrap();b.push(b'\n');fs::write(Path::new(ROOT).join(name),&b).unwrap();println!("{}",json!({"artifact":name,"bytes":b.len(),"sha256":sha(&b)}));}
fn source_availability(d:&Dictionary)->Vec<Value>{let m=d.metadata();let r=d.registry().as_document();let mut sources:Vec<_>=r.sources.iter().collect();sources.sort_by_key(|s|&s.id);sources.into_iter().map(|s|{let cs:Vec<_>=m.collections.iter().filter(|x|x.source==s.id).collect();let ps:Vec<_>=m.components.iter().filter(|x|cs.iter().any(|c|c.id==x.collection)).collect();let rs:Vec<_>=m.releases.iter().filter(|x|ps.iter().any(|p|p.id==x.component)).collect();assert!(rs.iter().all(|x|x.selected&&x.availability==Availability::Available));let mut caps=Vec::new();for x in &rs{for c in &x.captures{if !caps.contains(c){caps.push(c.clone());}}}json!({"source":s,"aliases":r.aliases.iter().filter(|x|x.source==s.id).collect::<Vec<_>>(),"lineage":r.lineage.iter().filter(|x|x.source==s.id).collect::<Vec<_>>(),"collections":cs,"components":ps,"releases":rs,"selected_available_release_ids":rs.iter().map(|x|&x.id).collect::<Vec<_>>(),"loaded_captures":caps,"missing_captures":[],"owned_head":null,"selectable":true,"reason":null})}).collect()}
fn expected_hit(d:&Dictionary,a:&AssertionRecord)->Value{let m=d.metadata();let r=d.registry().as_document();let e=m.entries.iter().find(|e|e.id==a.entry).unwrap();let cap=d.capture(&a.occurrence.capture).unwrap();let raw=d.occurrence(&a.occurrence).unwrap();let sb=r.snapshots.iter().find(|s|s.snapshot.namespace()==a.occurrence.capture.namespace&&s.snapshot.sha256()==a.occurrence.capture.sha256).unwrap();let attr=r.occurrences.iter().find(|o|o.occurrence.locator()==a.occurrence.locator&&o.occurrence.snapshot().namespace()==a.occurrence.capture.namespace&&o.occurrence.snapshot().sha256()==a.occurrence.capture.sha256).unwrap();let cs:Vec<_>=m.contexts.iter().filter(|x|x.assertion==a.id).collect();let fs:Vec<_>=m.forms.iter().filter(|x|x.entry==e.id).collect();let es:Vec<_>=m.etymologies.iter().filter(|x|x.assertion==a.id).collect();let collections:Vec<_>=m.collections.iter().filter(|x|x.source==e.source).collect();let components:Vec<_>=m.components.iter().filter(|x|collections.iter().any(|c|c.id==x.collection)).collect();let releases:Vec<_>=m.releases.iter().filter(|x|components.iter().any(|c|c.id==x.component)&&x.selected&&x.availability==Availability::Available).collect();let mut owners:BTreeSet<_>=[&e.id,&a.id].into_iter().collect();owners.extend(cs.iter().map(|x|&x.id));owners.extend(fs.iter().map(|x|&x.id));owners.extend(es.iter().map(|x|&x.id));owners.extend(collections.iter().map(|x|&x.id));owners.extend(components.iter().map(|x|&x.id));owners.extend(releases.iter().map(|x|&x.id));json!({"occurrence_id":tuple(&a.occurrence),"entry":e,"assertion":a,"capture":cap.metadata,"raw":raw,"snapshot_attribution":sb,"occurrence_attribution":attr,"contributor":attr.contributor.as_ref().and_then(|id|r.contributors.iter().find(|c|&c.id==id)),"distributor":sb.distributor.as_ref().and_then(|id|r.distributors.iter().find(|c|&c.id==id)),"release_ids":releases.iter().filter(|x|x.assertions.contains(&a.id)).map(|x|&x.id).collect::<Vec<_>>(),"contexts":cs,"frames":[],"forms":fs,"etymologies":es,"relations":[],"editorial_senses":[],"computations":[],"annotations":[],"extensions":m.extensions.iter().filter(|x|owners.contains(&x.owner)).collect::<Vec<_>>(),"owned_revision_ids":[],"tombstoned_by":[]})}
fn check_response(d:&Dictionary,all:&DictionaryExactResponse,state:&str){let m=d.metadata();let r=d.registry().as_document();assert!(m.frames.is_empty()&&m.relations.is_empty()&&m.computations.is_empty()&&m.annotations.is_empty()&&m.owned_revisions.is_empty()&&m.owned_heads.is_empty()&&m.editorial_senses.is_empty());let mut groups=Vec::new();let mut totals=Vec::new();for (sid,ns,locs) in [("lensisku","captured:lensisku:jbotci:en",vec!["/13306","/13307"]),("lensisku","captured:lensisku:la-lojban:en",vec!["/4095"]),("llg","captured:llg:gismu",vec!["357"]),("sutysisku","captured:sutysisku:parsed-en",vec!["/11309"])]{for loc in locs{let a=m.assertions.iter().find(|a|a.occurrence.capture.namespace==ns&&a.occurrence.locator==loc).unwrap();let hit=expected_hit(d,a);assert_eq!(hit["entry"]["source"],sid);groups.push((sid.to_string(),hit));}}
 groups.sort_by_key(|(s,h)|(s.clone(),h["occurrence_id"].as_str().unwrap().to_owned()));let mut gs=Vec::new();for sid in ["lensisku","llg","sutysisku"]{let source=r.sources.iter().find(|s|s.id.as_str()==sid).unwrap();let hits:Vec<_>=groups.iter().filter(|(s,_)|s==sid).map(|(_,h)|h).collect();let n=hits.len();totals.push(json!({"source":source,"occurrences":n,"distinct_spellings":1}));gs.push(json!({"source":source,"full_count":n,"returned_count":n,"partial":false,"hits":hits}));}let expect=json!({"version":1,"policy":"exact-entry-v1","store_schema_version":1,"catalogue_revision":m.catalogue_revision,"state_sha256":state,"spelling":"farvi","resolved_sources":["lensisku","llg","sutysisku"],"native_candidate_occurrences":5,"totals":{"occurrences":5,"source_groups":3,"distinct_spellings":1},"source_totals":totals,"availability":source_availability(d),"groups":gs,"next_cursor":null,"code_notices":m.code_notices});let actual=serde_json::to_value(all).unwrap();assert!(actual==expect,"complete farvi response differs from independently assembled expected fields");save("farvi-expected.json",&expect);save("farvi-rust.json",&actual);}
fn main(){
 let t=stage("full_load_compose");
 macro_rules! bytes_equal{($direct:ident,$umbrella:ident)=>{{assert_eq!($direct::release_bytes(),vlajmaji::$umbrella::release_bytes());assert_eq!($direct::seal_bytes(),vlajmaji::$umbrella::seal_bytes());let seal=PackSeal::from_json_bytes($direct::seal_bytes()).unwrap();assert_eq!(seal.payload_kind,PackPayloadKind::Full);println!("{}",json!({"pack":seal.pack_id,"release_bytes":seal.release_bytes,"release_sha256":seal.release_sha256,"seal_sha256":sha($direct::seal_bytes())}));}}}
 bytes_equal!(vlajmaji_data_lensisku_jbotci,data_lensisku_jbotci);bytes_equal!(vlajmaji_data_llg,data_llg);bytes_equal!(vlajmaji_data_la_lojban,data_la_lojban);bytes_equal!(vlajmaji_data_sutysisku,data_sutysisku);
 let models=vec![vlajmaji_data_lensisku_jbotci::load().unwrap(),vlajmaji_data_llg::load().unwrap(),vlajmaji_data_la_lojban::load().unwrap(),vlajmaji_data_sutysisku::load().unwrap()];let d=compose_dictionaries(models).unwrap();let m=d.metadata();assert_eq!((m.assertions.len(),m.entries.len(),m.contexts.len(),m.forms.len(),m.etymologies.len(),m.extensions.len()),(78361,76722,177210,11598,3513,138107));let canonical=d.to_json_bytes().unwrap();let state=sha(&canonical);let canonical_len=canonical.len();println!("{}",json!({"canonical_bytes":canonical_len,"canonical_sha256":state}));drop(canonical);done("full_load_compose",t);
 let store=Path::new(ROOT).join("full-four-pack-store01");let t=stage("store_create");let created=DictionaryStore::create(&store,&d).unwrap();let summary=serde_json::to_value(created.summary().unwrap()).unwrap();save("store-summary.json",&summary);drop(created);done("store_create",t);
 let db=store.join("dictionary.sqlite3");let before=file_sha(&db);let t=stage("readonly_reopen_canonical");let reopened=DictionaryStore::open(&store).unwrap();let blob=reopened.canonical_bytes().unwrap();assert_eq!(blob.len(),canonical_len);assert_eq!(sha(&blob),state);assert_eq!(reopened.recorded_state_sha256(),state);drop(blob);drop(reopened);done("readonly_reopen_canonical",t);
 let t=stage("verify_all");let verification=DictionaryStoreVerification::verify(&store,DictionaryStoreVerificationCheck::All).unwrap();assert!(verification.ok&&verification.checks.len()==6&&verification.checks.iter().all(|c|c.status==DictionaryStoreCheckStatus::Passed));save("verify-all.json",&serde_json::to_value(verification).unwrap());done("verify_all",t);
 let t=stage("query_pages_references");let engine=DictionarySearchEngine::open(&store).unwrap();let all=engine.exact("farvi",Default::default()).unwrap();check_response(&d,&all,&state);
 for (id,alias,n) in [("lensisku","LSK",3),("llg","LLG",1),("sutysisku","SUT",1)]{let opts=|s:&str|DictionaryExactOptions{sources:vec![s.into()],..Default::default()};let a=engine.exact("farvi",opts(id)).unwrap();let b=engine.exact("farvi",opts(alias)).unwrap();assert_eq!(a,b);assert_eq!(a.totals.occurrences,n);assert_eq!(a.groups,all.groups.iter().filter(|g|g.source.id.as_str()==id).cloned().collect::<Vec<_>>());}
 assert!(matches!(engine.exact("farvi",DictionaryExactOptions{sources:vec!["la-lojban".into()],..Default::default()}),Err(DictionaryQueryError::Registry(RegistryError::UnknownSource(_)))));assert!(engine.exact("farvi",DictionaryExactOptions{sources:vec!["arc-review-unknown".into()],..Default::default()}).is_err());
 let flat=all.groups.iter().flat_map(|g|g.hits.iter().cloned()).collect::<Vec<_>>();for size in [0,1,2,3,8]{let mut cursor=None;let mut got=Vec::new();let mut pages=0;loop{let p=engine.exact("farvi",DictionaryExactOptions{page_size:Some(size),cursor,..Default::default()}).unwrap();assert_eq!(p.totals,all.totals);assert_eq!(p.source_totals,all.source_totals);assert_eq!(p.availability,all.availability);got.extend(p.groups.iter().flat_map(|g|g.hits.iter().cloned()));pages+=1;cursor=p.next_cursor;if cursor.is_none(){break}assert!(pages<=5);}if size==0{assert!(got.is_empty())}else{assert_eq!(got,flat)}println!("{}",json!({"page_size":size,"pages":pages,"hits":got.len()}));}
 let first=&flat[0];assert_eq!(engine.resolve(&RelationTarget::Local(LocalRef::Assertion(first.assertion.id.clone()))).unwrap().status,ReferenceStatus::Resolved);assert_eq!(engine.resolve(&RelationTarget::Unknown).unwrap().status,ReferenceStatus::Unknown);assert_eq!(engine.resolve(&RelationTarget::Unresolved("explicit unknown origin".into())).unwrap().status,ReferenceStatus::Unresolved);for lr in [LocalRef::Entry(first.assertion.id.clone()),LocalRef::Entry(EntityId::new("arc-review-missing-entry").unwrap())]{assert!(matches!(engine.resolve(&RelationTarget::Local(lr)),Err(DictionaryQueryError::InvalidReference{..})));}
 for hit in flat.iter().filter(|h|h.occurrence_attribution.as_ref().and_then(|a|a.native_assertion_id.as_deref())==Some("333")){let release=hit.release_ids[0].clone();let target=RelationTarget::Catalog(CatalogTarget{source:hit.entry.source.clone(),release,native_entry_id:None,native_assertion_id:Some("333".into()),occurrence:None});let x=engine.resolve(&target).unwrap();assert_eq!(x.status,ReferenceStatus::Resolved);assert_eq!(x.confirmed.len(),1);assert_eq!(x.confirmed[0].assertion,hit.assertion);}
 let excluded=d.metadata().assertions.iter().find(|a|a.occurrence.capture.namespace=="captured:sutysisku:parsed-en"&&a.occurrence.locator=="/23602").unwrap();let release=d.metadata().releases.iter().find(|r|r.assertions.contains(&excluded.id)).unwrap();let target=RelationTarget::Catalog(CatalogTarget{source:SourceId::new("sutysisku").unwrap(),release:release.id.clone(),native_entry_id:Some("zoizoizoi".into()),native_assertion_id:None,occurrence:Some(excluded.occurrence.clone())});let x=engine.resolve(&target).unwrap();assert_eq!(x.status,ReferenceStatus::Resolved);assert_eq!(x.confirmed.len(),1);assert!(x.confirmed[0].payload_present&&!x.confirmed[0].current_eligible);assert_eq!(x.confirmed[0].raw.as_ref().unwrap(),d.occurrence(&excluded.occurrence).unwrap());assert_eq!(engine.exact("zoizoizoi",DictionaryExactOptions{sources:vec!["SUT".into()],..Default::default()}).unwrap().totals.occurrences,0);assert_eq!(engine.exact("arc-review-absent-word",Default::default()).unwrap().totals.occurrences,0);drop(engine);done("query_pages_references",t);
 let after=file_sha(&db);assert_eq!(before,after);save("runtime-summary.json",&json!({"status":"PASS","source":"7b1c565ebf6c8a423e04211b599006b8c21d65d9","profile":"release","store":store,"db_pre_sha256":before,"db_post_sha256":after,"canonical_bytes":canonical_len,"canonical_sha256":state,"farvi_complete_response_equal":true,"raw_native_sql_pending":true}));
}
